package omnicore

import (
	"encoding/json"
	"math"
	"os"
	"testing"
)

// testdata/vectors.json is generated by web/test/gen-vectors.mjs --json from
// the JS reference implementation.
type vector struct {
	Name     string       `json:"name"`
	Code     string       `json:"code"`
	Curve    [][2]float64 `json:"curve"`
	Steps    [][5]int64   `json:"steps"`
	RawAccel struct {
		Right, Left, Up, Down float64
		Errors8               []float64 `json:"errors8"`
		MaxErrorPct           float64   `json:"maxErrorPct"`
		RMSErrorPct           float64   `json:"rmsErrorPct"`
		MaxSkewDeg            float64   `json:"maxSkewDeg"`
	} `json:"rawAccel"`
}

func loadVectors(t *testing.T) []vector {
	t.Helper()
	b, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v []vector
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	if len(v) == 0 {
		t.Fatal("no vectors")
	}
	return v
}

func TestVectorsMatchJS(t *testing.T) {
	for _, v := range loadVectors(t) {
		cfg, err := DecodeProfileCode(v.Code)
		if err != nil {
			t.Fatalf("%s: %v", v.Name, err)
		}
		if got := EncodeProfileCode(cfg); got != v.Code {
			t.Errorf("%s: code round trip %q != %q", v.Name, got, v.Code)
		}
		for _, c := range v.Curve {
			if g := GainAt(cfg.Gains(), c[0], cfg.Linear()); math.Abs(g-c[1]) > 1e-9 {
				t.Errorf("%s: gain at %.1f = %.9f, JS %.9f", v.Name, c[0], g, c[1])
			}
		}
		e := NewEngine(cfg)
		var sx, sy, jx, jy int64
		mismatches := 0
		for i, s := range v.Steps {
			ox, oy := e.Process(int32(s[0]), int32(s[1]), uint64(s[2]))
			if int64(ox) != s[3] || int64(oy) != s[4] {
				mismatches++
			}
			sx, sy, jx, jy = sx+int64(ox), sy+int64(oy), jx+s[3], jy+s[4]
			if d := math.Max(math.Abs(float64(sx-jx)), math.Abs(float64(sy-jy))); d > 1 {
				t.Fatalf("%s step %d: totals drifted by %v", v.Name, i, d)
			}
		}
		if mismatches > len(v.Steps)/100 {
			t.Errorf("%s: %d/%d steps differ from JS", v.Name, mismatches, len(v.Steps))
		}
		f := FitRawAccel(cfg)
		for _, p := range [][2]float64{{f.Right, v.RawAccel.Right}, {f.Left, v.RawAccel.Left}, {f.Up, v.RawAccel.Up}, {f.Down, v.RawAccel.Down},
			{f.MaxErrorPct, v.RawAccel.MaxErrorPct}, {f.RMSErrorPct, v.RawAccel.RMSErrorPct}, {f.MaxSkewDeg, v.RawAccel.MaxSkewDeg}} {
			if math.Abs(p[0]-p[1]) > 1e-9 {
				t.Errorf("%s: raw accel fit %v != JS %v", v.Name, p[0], p[1])
			}
		}
		for k := range f.Errors8 {
			if math.Abs(f.Errors8[k]-v.RawAccel.Errors8[k]) > 1e-9 {
				t.Errorf("%s: raw accel error %d %v != JS %v", v.Name, k, f.Errors8[k], v.RawAccel.Errors8[k])
			}
		}
	}
}

func TestSanitizeAndDefaults(t *testing.T) {
	c := DefaultConfig()
	c.NPoints, c.Flags, c.ResetMs, c.RotationCdeg = 40, 0xff, 0, 9000
	c.GainsQ12[0], c.GainsQ12[1] = 1, 65535
	c.Label = "a\tb\x00zzz"
	c.Sanitize()
	if c.NPoints != 16 || c.Flags != 7 || c.ResetMs != 40 || c.RotationCdeg != 4500 {
		t.Fatalf("clamp: %+v", c)
	}
	if c.GainsQ12[0] != GainMin || c.GainsQ12[1] != GainMax || c.Label != "a?b" {
		t.Fatalf("gains/label: %v %q", c.GainsQ12[:2], c.Label)
	}
	e := NewEngine(DefaultConfig())
	for i := 0; i < 500; i++ {
		dx, dy := int32(i%7-3), int32(i%5-2)
		if ox, oy := e.Process(dx, dy, uint64(i)*1000); ox != dx || oy != dy {
			t.Fatalf("flat profile changed (%d,%d) -> (%d,%d)", dx, dy, ox, oy)
		}
	}
	if _, err := DecodeProfileCode("omni1.AAAA"); err == nil {
		t.Fatal("short code accepted")
	}
	if _, err := DecodeProfileCode("hello"); err == nil {
		t.Fatal("garbage accepted")
	}
}

func TestRawAccelFitShapes(t *testing.T) {
	flat := FitRawAccel(DefaultConfig())
	if math.Abs(flat.Right-1) > 1e-9 || flat.MaxErrorPct > 1e-9 || flat.MaxSkewDeg > 1e-9 {
		t.Fatalf("flat: %+v", flat)
	}
	// A pure left/right asymmetry is mostly representable.
	g := make([]float64, 8)
	for k := range g {
		g[k] = 1 + 0.06*math.Cos(float64(k)*math.Pi/4)
	}
	f := FitRawAccel(ConfigFromGains(g, false))
	if f.Right < 1.05 || f.Left > 0.95 || f.MaxErrorPct > 2 {
		t.Fatalf("cos fit: %+v", f)
	}
}
